package com.example.ancapp.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewmodel.CreationExtras
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.Patient
import com.example.ancapp.data.Visit
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

class AncViewModel(private val repository: AncRepository) : ViewModel() {

    private val _patients = MutableStateFlow(repository.loadPatients())
    val patients: StateFlow<List<Patient>> = _patients.asStateFlow()

    fun patient(patientId: String): Patient? = _patients.value.find { it.id == patientId }

    fun addVisit(patientId: String, visit: Visit) {
        _patients.update { list ->
            list.map { patient ->
                if (patient.id == patientId) patient.copy(visits = patient.visits + visit) else patient
            }
        }
        repository.savePatients(_patients.value)
    }

    companion object {
        fun factory(repository: AncRepository): ViewModelProvider.Factory =
            object : ViewModelProvider.Factory {
                override fun <T : ViewModel> create(modelClass: Class<T>, extras: CreationExtras): T {
                    @Suppress("UNCHECKED_CAST")
                    return AncViewModel(repository) as T
                }
            }
    }
}

