@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientDetailScreen(
    patient: Patient,
    onBack: () -> Unit,
    onAddVisit: () -> Unit,
) {
    val visits = patient.visits.sortedByDescending { it.visitDate.toLocalDate() }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(patient.name) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = onAddVisit) {
                Icon(Icons.Filled.Add, contentDescription = "Record ANC visit")
            }
        },
    ) { padding ->
        LazyColumn(
            contentPadding = PaddingValues(16.dp, padding.calculateTopPadding() + 8.dp, 16.dp, 88.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
            modifier = Modifier.fillMaxWidth(),
        ) {
            item {
                PatientSummary(patient)
                HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                Text("Visit history", fontWeight = FontWeight.Bold)
            }
            if (visits.isEmpty()) {
                item { Text("No ANC visits recorded yet.") }
            }
            items(visits, key = { it.id }) { visit -> VisitRow(visit) }
        }
    }
}

@Composable
private fun PatientSummary(patient: Patient) {
    Column {
        Text("Age ${ageInYears(patient.dateOfBirth)}")
        Text("Due ${patient.estimatedDueDate.toLocalDate().toDisplayString()}")
        Text("${currentWeeksPregnant(patient.estimatedDueDate)} weeks pregnant")
    }
}

@Composable
private fun VisitRow(visit: Visit) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text(visit.visitDate.toLocalDate().toDisplayString(), fontWeight = FontWeight.Bold)
            Text("Gestational age: ${visit.gestationalAgeWeeks} weeks")
            Text("Weight: ${visit.weightKg} kg")
            Text("BP: ${visit.systolicBp}/${visit.diastolicBp} mmHg")
            if (visit.hemoglobin != null) {
                Text("Hemoglobin: ${visit.hemoglobin} g/dL")
            }
            val signs = visit.dangerSigns.filter { it != DangerSign.NONE }
            if (signs.isNotEmpty()) {
                Text("Danger signs: ${signs.joinToString { it.label }}")
            }
            if (visit.notes.isNotBlank()) {
                Text("Notes: ${visit.notes}")
            }
        }
    }
}

