import com.example.ancapp.data.toDisplayString
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneOffset
import java.util.UUID

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddVisitScreen(
    onBack: () -> Unit,
    onSave: (Visit) -> Unit,
) {
    var visitDate by remember { mutableStateOf(LocalDate.now()) }
    var showDatePicker by remember { mutableStateOf(false) }
    var gestationalAge by remember { mutableStateOf("") }
    var weight by remember { mutableStateOf("") }
    var systolic by remember { mutableStateOf("") }
    var diastolic by remember { mutableStateOf("") }
    var notes by remember { mutableStateOf("") }
    val selectedSigns = remember { mutableStateOf(setOf<DangerSign>(DangerSign.NONE)) }

    val gestationalAgeValue = gestationalAge.toIntOrNull()
    val weightValue = weight.toDoubleOrNull()
    val systolicValue = systolic.toIntOrNull()
    val diastolicValue = diastolic.toIntOrNull()
    val isValid = gestationalAgeValue != null && weightValue != null &&
        systolicValue != null && diastolicValue != null

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Record ANC visit") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
            )
        },
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .padding(16.dp)
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            OutlinedButton(onClick = { showDatePicker = true }, modifier = Modifier.fillMaxWidth()) {
                Text("Visit date: ${visitDate.toDisplayString()}")
            }

            OutlinedTextField(
                value = gestationalAge,
                onValueChange = { gestationalAge = it.filter(Char::isDigit) },
                label = { Text("Gestational age (weeks)") },
                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = KeyboardType.Number),
                modifier = Modifier.fillMaxWidth(),
            )

            OutlinedTextField(
                value = weight,
                onValueChange = { weight = it.filter { c -> c.isDigit() || c == '.' } },
                label = { Text("Weight (kg)") },
                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.fillMaxWidth(),
            )

            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                OutlinedTextField(
                    value = systolic,
                    onValueChange = { systolic = it.filter(Char::isDigit) },
                    label = { Text("Systolic (mmHg)") },
                    keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = KeyboardType.Number),
                    modifier = Modifier.weight(1f),
                )
                OutlinedTextField(
                    value = diastolic,
                    onValueChange = { diastolic = it.filter(Char::isDigit) },
                    label = { Text("Diastolic (mmHg)") },
                    keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = KeyboardType.Number),
                    modifier = Modifier.weight(1f),
                )
            }

            Text("Danger signs")
            DangerSign.entries.forEach { sign ->
                Row {
                    Checkbox(
                        checked = sign in selectedSigns.value,
                        onCheckedChange = { checked ->
                            selectedSigns.value = when {
                                sign == DangerSign.NONE && checked -> setOf(DangerSign.NONE)
                                sign == DangerSign.NONE && !checked -> emptySet()
                                checked -> (selectedSigns.value - DangerSign.NONE) + sign
                                else -> selectedSigns.value - sign
                            }
                        },
                    )
                    Text(sign.label, modifier = Modifier.padding(top = 12.dp))
                }
            }

            OutlinedTextField(
                value = notes,
                onValueChange = { notes = it },
                label = { Text("Notes") },
                modifier = Modifier.fillMaxWidth(),
                minLines = 3,
            )

            Button(
                onClick = {
                    val signs = selectedSigns.value.ifEmpty { setOf(DangerSign.NONE) }.toList()
                    onSave(
                        Visit(
                            id = UUID.randomUUID().toString(),
                            visitDate = visitDate.toString(),
                            gestationalAgeWeeks = gestationalAgeValue!!,
                            weightKg = weightValue!!,
                            systolicBp = systolicValue!!,
                            diastolicBp = diastolicValue!!,
                            dangerSigns = signs,
                            notes = notes.trim(),
                        ),
                    )
                },
                enabled = isValid,
                modifier = Modifier.fillMaxWidth(),
            ) {
                Text("Save visit")
            }
        }
    }

    if (showDatePicker) {
        val state = rememberDatePickerState(
            initialSelectedDateMillis = visitDate.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli(),
        )
        DatePickerDialog(
            onDismissRequest = { showDatePicker = false },
            confirmButton = {
                TextButton(onClick = {
                    state.selectedDateMillis?.let { millis ->
                        visitDate = Instant.ofEpochMilli(millis).atZone(ZoneOffset.UTC).toLocalDate()
                    }
                    showDatePicker = false
                }) { Text("OK") }
            },
            dismissButton = {
                TextButton(onClick = { showDatePicker = false }) { Text("Cancel") }
            },
        ) {
            DatePicker(state = state)
        }
    }
}

